style.css:
@-moz-document domain("youtube.com") {
/* Fondo oscuro elegante */
  body {
    background-color: #0f0f0f !important;
    color: #ffffff !important;
  }

  /* Elimina animaciones y efectos pesados */
  * {
    transition: none !important;
    animation: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
  }

  /* Centra el contenido y ajusta para monitores ultrapanorámicos */
  ytd-page-manager {
    max-width: 100% !important;
    margin: 0 auto !important;
    padding: 0 40px !important;
    display: flex !important;
    justify-content: center !important;
  }

  /* Fuerza 6 columnas en la cuadrícula principal */
  ytd-rich-grid-renderer #contents {
    display: grid !important;
    grid-template-columns: repeat(6, 1fr) !important;
    gap: 24px !important;
    justify-content: center !important;
  }

  /* Oculta Shorts y secciones no deseadas */
  ytd-rich-section-renderer,
  ytd-reel-shelf-renderer {
    display: none !important;
  }

  /* Ajustes visuales suaves para títulos y texto */
  #video-title {
    font-size: 14px !important;
    font-weight: 500 !important;
    color: #e0e0e0 !important;
  }

  /* Menú lateral compacto */
  ytd-mini-guide-renderer {
    width: 60px !important;
  }

  /* Elimina bordes innecesarios */
  ytd-app {
    border: none !important;
  }
}
